/** @returns {{iata:string, lat:number, lng:number, name:string, country:string}|null} */
export const airport = (iata) => {
  if (!iata) return null;
  const row = AIRPORTS[String(iata).toUpperCase()];
  if (!row) return null;
  return { iata: String(iata).toUpperCase(), lat: row[0], lng: row[1], name: row[2], country: row[3] };
};
